      },
      {
        "step": "Check for runaway log or diagnostic data growth",
        "hypothesis": "Non-database files (logs, diagnostic.data) are consuming the disk.",
        "how_to_check": "du -sh /var/lib/mongodb/* /var/log/mongodb"
      },
      {
        "step": "Verify TTL index functionality",
        "hypothesis": "A TTL index is not working, causing data to accumulate indefinitely.",
        "how_to_check": "db.collection.getIndexes() to confirm expireAfterSeconds"
      },
